EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    // Initialize the current position in the stream
    uint64 currentPosition = 0;

    // Check if the stream is valid and can be read
    if (!DataStream.isValid()) {
        return nullptr;
    }

    // Read the ID from the stream
    uint64 id = 0;
    size_t bytesRead = DataStream.read(reinterpret_cast<char*>(&id), sizeof(id));
    if (bytesRead != sizeof(id)) {
        return nullptr; // Failed to read the full ID
    }

    // Validate the ID
    if (!Context.isValidId(id)) {
        return nullptr; // Invalid ID
    }

    // Read the size of the element
    uint64 size = 0;
    bytesRead = DataStream.read(reinterpret_cast<char*>(&size), sizeof(size));
    if (bytesRead != sizeof(size)) {
        return nullptr; // Failed to read the full size
    }

    // Check if the size is valid and within the maximum data size
    if (size > MaxDataSize) {
        return nullptr; // Size exceeds the maximum allowed data size
    }

    // Check if the size is valid for the current level
    if (UpperLevel > static_cast<int>(MaxLowerLevel)) {
        return nullptr; // Exceeds the maximum allowed lower level
    }

    // Calculate the new position after reading the ID and size
    currentPosition += sizeof(id) + sizeof(size);

    // Check if the size is valid and the remaining data is sufficient
    if (currentPosition + size > MaxDataSize) {
        return nullptr; // Not enough data to satisfy the size
    }

    // Create the EBML element
    EbmlElement* element = Context.createElement(id, size);
    if (!element) {
        return nullptr; // Failed to create the element
    }

    // Check if dummy elements are allowed
    if (!AllowDummyElt && element->isDummy()) {
        delete element;
        return nullptr; // Dummy element not allowed
    }

    // Update the upper level
    UpperLevel++;

    return element;
}
